"""Extract manually traced silhouettes from ONE original raster; never redraw RGB.
Coordinates are in the original 1536x1024 canvas. Run with Pillow and numpy.
"""
from pathlib import Path
from PIL import Image, ImageDraw
import numpy as np
ROOT=Path(__file__).resolve().parents[1]
base=Image.open(ROOT/'public/assets/00_base_scene.png').convert('RGB')
assert base.size==(1536,1024)
# Contours follow visible object boundaries, not rectangular hit regions.
contours={
'01_dove_olive':[(89,24),(98,38),(100,23),(106,49),(106,25),(111,51),(118,68),(130,81),(140,87),(154,89),(162,83),(170,82),(176,87),(178,94),(179,96),(172,97),(164,115),(152,123),(144,125),(143,133),(132,140),(118,142),(111,136),(106,128),(104,119),(126,115),(130,107),(117,107),(111,101),(102,87),(96,70),(92,55)],
'02_scroll':[(110,640),(114,633),(122,630),(129,631),(170,625),(172,618),(181,618),(190,619),(219,611),(223,612),(224,615),(230,617),(235,628),(235,638),(232,645),(224,649),(181,659),(145,665),(123,664),(115,660),(110,650)],
'03_clay_jar':[(656,551),(671,550),(677,548),(692,550),(701,551),(701,558),(696,563),(696,574),(701,590),(714,606),(721,624),(722,645),(716,665),(697,668),(677,675),(654,680),(646,662),(641,642),(640,622),(644,607),(652,595),(661,584),(662,565),(656,558)],
'04_fish':[(1315,820),(1338,819),(1363,821),(1389,826),(1404,820),(1414,817),(1404,825),(1413,823),(1402,832),(1420,846),(1442,852),(1450,859),(1449,864),(1467,870),(1488,868),(1500,867),(1491,880),(1488,894),(1492,913),(1477,907),(1464,896),(1457,886),(1438,882),(1422,881),(1425,890),(1430,895),(1425,896),(1415,890),(1408,880),(1390,877),(1384,873),(1391,887),(1384,884),(1379,875),(1378,869),(1366,866),(1346,855),(1329,845),(1314,835),(1312,831),(1325,835),(1320,828)],
'05_grapes':[(274,786),(281,782),(291,785),(294,777),(301,775),(312,780),(315,773),(322,769),(331,772),(334,781),(340,784),(346,791),(345,800),(351,809),(350,821),(346,827),(350,839),(345,849),(349,858),(344,869),(338,872),(340,883),(334,891),(326,889),(322,883),(314,880),(307,874),(305,863),(299,860),(295,851),(286,847),(284,841),(276,839),(274,831),(268,826),(269,817),(271,812),(269,805),(270,794)],
'06_oil_lamp':[(634,289),(642,286),(644,283),(648,281),(652,284),(658,285),(666,289),(673,284),(678,285),(678,290),(671,295),(667,300),(640,302),(633,298),(628,298),(625,294),(626,289),(630,288)],
'07_bread':[(818,877),(821,866),(831,853),(840,844),(853,836),(866,831),(883,825),(902,824),(920,827),(932,837),(945,849),(951,861),(951,870),(947,877),(936,883),(910,889),(877,896),(845,900),(830,897),(821,892)],
'08_harp':[(1358,548),(1364,531),(1374,399),(1374,375),(1381,369),(1395,371),(1396,378),(1409,380),(1427,398),(1441,406),(1455,405),(1474,398),(1481,402),(1486,412),(1483,425),(1469,458),(1420,538),(1393,541),(1380,545),(1378,550)],
'09_rainbow':[(959,239),(970,219),(987,199),(1009,179),(1034,164),(1061,150),(1086,141),(1114,136),(1141,136),(1169,139),(1198,147),(1226,158),(1252,173),(1246,188),(1220,174),(1193,164),(1167,156),(1140,152),(1115,152),(1090,156),(1067,165),(1043,177),(1021,191),(1000,208),(982,226),(972,241)]
}
for name,points in contours.items():
 mask=Image.new('L',base.size); d=ImageDraw.Draw(mask);d.polygon(points,fill=255)
 if name=='01_dove_olive':
  # Olive twig: preserve only green leaf pixels plus its slender stem.
  rgb=np.asarray(base); a=np.asarray(mask).copy(); r,g,b=rgb[:,:,0].astype(int),rgb[:,:,1].astype(int),rgb[:,:,2].astype(int)
  yy,xx=np.indices(a.shape); leaf=(xx>=172)&(xx<=205)&(yy>=77)&(yy<=121)&(g>r*.87)&(g>b*1.3)&(r<160)&(g<175)
  a[leaf]=255;mask=Image.fromarray(a);d=ImageDraw.Draw(mask);d.line([(173,120),(181,103),(194,88)],fill=255,width=1)
 if name=='03_clay_jar':
  d.polygon([(697,568),(707,565),(717,569),(724,577),(727,590),(724,603),(720,613),(715,603),(720,591),(719,581),(714,574),(707,573),(700,581)],fill=255)
 if name=='06_oil_lamp':
  d.polygon([(674,266),(672,276),(673,282),(676,282),(677,275)],fill=255)
  d.line([(675,281),(675,286)],fill=255,width=2)
  d.polygon([(628,291),(632,291),(635,295),(632,296),(628,294)],fill=0)
 if name=='08_harp':
  # Open interior stays transparent, including gaps between individual strings.
  d.polygon([(1390,398),(1400,399),(1414,411),(1428,417),(1443,419),(1465,414),(1450,442),(1424,479),(1383,532)],fill=0)
  for p,q in [((1392,400),(1383,528)),((1398,401),(1389,520)),((1404,405),(1396,511)),((1410,409),(1403,502)),((1416,413),(1410,493)),((1422,416),(1417,484)),((1428,418),(1424,474)),((1434,419),(1431,464)),((1440,420),(1438,454)),((1446,419),(1445,444)),((1452,418),(1452,433)),((1458,416),(1458,424))]:d.line([p,q],fill=255,width=1)
 rgba=base.copy().convert('RGBA');rgba.putalpha(mask)
 # Zero transparent RGB for compact PNG; visible RGB remains bit-identical.
 arr=np.array(rgba);arr[arr[:,:,3]==0,:3]=0
 Image.fromarray(arr).save(ROOT/f'public/assets/{name}.png',optimize=True)
print('Extracted nine full-canvas RGBA layers from original scene pixels.')
